import random
import sympy as sp
random.seed(0)
a, b = sp.symbols('a b')
for k in range(1, 9):
    assert sp.rem(sp.expand(a**k - b**k), a - b, a) == 0
    if k % 2 == 0:
        assert sp.rem(sp.expand(a**k - b**k), a + b, a) == 0
    else:
        assert sp.rem(sp.expand(a**k + b**k), a + b, a) == 0
n = 0
for _ in range(2000):
    x, y = random.randint(-50, 50), random.randint(-50, 50)
    k = random.randint(1, 15)
    if x != y:
        assert (x**k - y**k) % (x - y) == 0
    if x + y != 0:
        if k % 2 == 0:
            assert (x**k - y**k) % (x + y) == 0
        else:
            assert (x**k + y**k) % (x + y) == 0
    n += 1
# boundary: parity of n matters; 2^3 - 1 = 7 is not divisible by 2 + 1 = 3, 2^2 + 1 = 5 is not either
assert (2**3 - 1) % 3 != 0 and (2**2 + 1) % 3 != 0
# worked example: m even, 8^m - 1 = 64^k - 1, so 63 divides; 8, 65, 42 do not always
for m in range(2, 40, 2):
    assert (8**m - 1) % 63 == 0
assert (8**2 - 1) % 8 and (8**2 - 1) % 65 and (8**2 - 1) % 42
print(f"CASES={n}")
print("BOUNDARY_OK")
